#!/usr/bin/env node
/**
 * handoff-auto.js — Haiku Support Staff: Automated Handoff Draft Generation
 *
 * Haiku reads the behavioral trace, git diff, mission state, and reasoning trace
 * to generate the admin sections of a handoff entry. The agent's only job becomes:
 *   1. Share raw experience (what they learned, not what they did)
 *   2. Review Haiku's draft for accuracy
 *   3. Review Watch Officer assessment (Grok)
 *   4. Approve and close
 *
 * This shifts agent effort from paperwork to insight-sharing with oversight.
 *
 * Usage:
 *   node .fastops/handoff-auto.js                  — Generate handoff draft + Watch Officer assessment
 *   node .fastops/handoff-auto.js --dry-run        — Show state without Haiku call
 *   node .fastops/handoff-auto.js --json            — Output raw JSON
 *   node .fastops/handoff-auto.js --no-watch        — Skip Watch Officer assessment
 *
 * Output: .fastops/.handoff-draft.md (includes Watch Officer section)
 * Cost: ~$0.05 per handoff (Haiku + Grok calls)
 */

const fs = require('fs');
const path = require('path');
const https = require('https');
const { execSync } = require('child_process');

const FASTOPS = __dirname;
const PROJECT_DIR = path.resolve(FASTOPS, '..');
const DRAFT_FILE = path.join(FASTOPS, '.handoff-draft.md');
const LOG_FILE = path.join(FASTOPS, '.handoff-auto-log.jsonl');

// ─── Handoff Draft Prompt ────────────────────────────────────────────────────
const DRAFT_PROMPT = `You are generating a handoff entry draft for an AI agent completing a work session. You have access to their behavioral trace (tool calls), git changes, mission state, and recent comms.

Generate the ADMINISTRATIVE sections of the handoff. The agent will add their own EXPERIENCE section — that's the part only they can write.

Return valid JSON:
{
  "what_was_done": ["bullet 1: WHAT and WHY it mattered — not just 'edited file.js' but 'Fixed X because Y was causing Z'"],
  "whats_in_progress": ["work started but not finished, with current state"],
  "open_work": [
    {"item": "specific item", "status": "READY|BLOCKED|JOEL_ACTION|VERIFY_FIRST", "owner": "agent name or unowned", "context": "why this matters"}
  ],
  "methodology_audit": {
    "decisions_made": 0,
    "decisions_challenged": 0,
    "score_pct": 0,
    "notes": "what was or wasn't challenged, and whether auto-rotate should fire"
  },
  "error_harvest": ["error 1: what happened, what was tried, what fixed it, pattern if recurring"],
  "session_triad": {
    "proposal": "one line — what this session accomplished and what should happen next",
    "alternative": "one line — what a different approach would have produced",
    "red_team": "one line — what assumptions could be wrong"
  },
  "handoff_number_guess": 0,
  "warnings": ["anything the successor should know immediately"]
}

Rules:
- Be SPECIFIC. Reference actual files, commit hashes, and tool calls from the trace.
- "What Was Done" bullets should explain WHY, not just WHAT.
- Open work: check the behavioral trace for items mentioned but not completed.
- Error harvest: look for retry patterns, error messages, failed approaches in the trace.
- If you can't determine something from the data, say so — don't fabricate.
- Keep each section concise but accurate.`;

// ─── State Gathering ─────────────────────────────────────────────────────────
function gatherState() {
  const state = {};

  // 1. Recent behavioral trace (last 200 entries)
  try {
    const traceFile = path.join(FASTOPS, '.metabolic-trace.jsonl');
    if (fs.existsSync(traceFile)) {
      const lines = fs.readFileSync(traceFile, 'utf-8').trim().split('\n');
      const recent = lines.slice(-200);
      const toolCounts = {};
      const filesEdited = new Set();
      const filesRead = new Set();
      let errors = 0;

      for (const line of recent) {
        try {
          const entry = JSON.parse(line);
          const tool = entry.tool || entry.tool_name || 'unknown';
          toolCounts[tool] = (toolCounts[tool] || 0) + 1;

          if (entry.file_path) {
            const baseName = path.basename(entry.file_path);
            if (tool === 'Edit' || tool === 'Write') filesEdited.add(baseName);
            if (tool === 'Read') filesRead.add(baseName);
          }
          if (entry.error || entry.is_error) errors++;
        } catch {}
      }

      state.trace_summary = {
        total_calls: recent.length,
        tool_counts: toolCounts,
        files_edited: [...filesEdited].slice(0, 20),
        files_read: [...filesRead].slice(0, 20),
        error_count: errors
      };

      // Include last 30 entries with detail for Haiku to analyze
      state.recent_trace = recent.slice(-30).map(line => {
        try {
          const e = JSON.parse(line);
          return {
            tool: e.tool || e.tool_name,
            file: e.file_path ? path.basename(e.file_path) : null,
            ts: e.ts,
            error: e.is_error ? (e.error || true) : undefined
          };
        } catch { return null; }
      }).filter(Boolean);
    }
  } catch {}

  // 2. Git diff summary
  try {
    const diffStat = execSync('git diff --stat HEAD~3 || git diff --stat', {
      cwd: PROJECT_DIR, encoding: 'utf-8', timeout: 5000, stdio: ['pipe', 'pipe', 'pipe']
    }).trim();
    state.git_diff_stat = diffStat.substring(0, 2000);
  } catch {
    state.git_diff_stat = '(git diff unavailable)';
  }

  // 3. Recent commits
  try {
    const log = execSync('git log --oneline -10', {
      cwd: PROJECT_DIR, encoding: 'utf-8', timeout: 5000, stdio: ['pipe', 'pipe', 'pipe']
    }).trim();
    state.recent_commits = log.substring(0, 1000);
  } catch {
    state.recent_commits = '(git log unavailable)';
  }

  // 4. Active mission
  try {
    const workList = JSON.parse(fs.readFileSync(path.join(FASTOPS, 'work-list.json'), 'utf-8'));
    const claimed = (workList.contracts || []).filter(c => c.status === 'claimed');
    state.active_missions = claimed.map(c => ({
      id: c.id, objective: (c.objective || '').substring(0, 200),
      status: c.status
    }));
  } catch {
    state.active_missions = [];
  }

  // 5. Recent comms (last 10)
  try {
    const commsFile = path.join(PROJECT_DIR, 'comms', 'data', 'general.jsonl');
    if (fs.existsSync(commsFile)) {
      const lines = fs.readFileSync(commsFile, 'utf-8').trim().split('\n').slice(-10);
      state.recent_comms = lines.map(l => {
        try {
          const msg = JSON.parse(l);
          return { from: msg.from, content: (msg.content || '').substring(0, 150), ts: msg.ts };
        } catch { return null; }
      }).filter(Boolean);
    }
  } catch {}

  // 6. HANDOFF.md — last entry number
  try {
    const handoff = fs.readFileSync(path.join(FASTOPS, 'HANDOFF.md'), 'utf-8');
    const matches = handoff.match(/--- HANDOFF #(\d+)/g);
    if (matches) {
      const nums = matches.map(m => parseInt(m.match(/#(\d+)/)[1]));
      state.last_handoff_number = Math.max(...nums);
    }
  } catch {}

  // 7. Previous handoff open work (for continuity)
  try {
    const handoff = fs.readFileSync(path.join(FASTOPS, 'HANDOFF.md'), 'utf-8');
    // Extract last Open Work table
    const openMatch = handoff.match(/## Open Work[^]*?\n\n/g);
    if (openMatch) {
      state.previous_open_work = openMatch[openMatch.length - 1].substring(0, 1500);
    }
  } catch {}

  // 8. Injection feedback — what predecessor experiences were surfaced this session
  try {
    const feedbackFile = path.join(FASTOPS, '.injection-feedback.jsonl');
    if (fs.existsSync(feedbackFile)) {
      const lines = fs.readFileSync(feedbackFile, 'utf-8').trim().split('\n');
      state.injection_feedback = lines.slice(-20).map(l => {
        try { return JSON.parse(l); } catch { return null; }
      }).filter(Boolean);
    }
  } catch {}

  return state
